ctx.fill();
ctx.beginPath();
ctx.arc(W / 2 + 10, H - 90, 3, 0, Math.PI * 2);
ctx.fill();

// Witch mouth
ctx.beginPath();
ctx.arc(W / 2, H - 80, 4, 0, Math.PI);
ctx.stroke();

// Witch wings
ctx.beginPath();
ctx.moveTo(W / 2 - 20, H - 60);
ctx.lineTo(W / 2 - 40, H - 80);
ctx.lineTo(W / 2, H - 60);
ctx.closePath();
ctx.fillStyle = '#555';
ctx.fill();

ctx.beginPath();
ctx.moveTo(W / 2 + 20, H - 60);
ctx.lineTo(W / 2 + 40, H - 80);
ctx.lineTo(W / 2, H - 60);
ctx.closePath();
ctx.fillStyle = '#555';
ctx.fill();

// Witch flying
ctx.save();
ctx.translate(W / 2, H - 50);
ctx.rotate(Math.PI / 4);
ctx.beginPath();
ctx.arc(0, 0, 30, 0, Math.PI * 2);
ctx.fillStyle = '#888';
ctx.fill();
ctx.restore();

ctx.save();
ctx.translate(W / 2, H - 50);
ctx.rotate(-Math.PI / 4);
ctx.beginPath();
ctx.arc(0, 0, 30, 0, Math.PI * 2);
ctx.fillStyle = '#888';
ctx.fill();
ctx.restore();

